package com.rdx.fullscreen.m6aoa;
import android.app.Service;import android.content.*;import android.hardware.usb.*;import android.os.*;import android.util.Log;import java.io.*;import java.util.UUID;
/** Explicit launch only. Frozen ARM rejects before any manager lookup, receiver or worker. */
public final class M6AoaService extends Service {
 public static final String ARM="com.rdx.fullscreen.m6aoa.ARM_REVIEWED_M6";
 private final Handler handler=new Handler();private M6Controller controller;private AndroidAoaAdapter usb;private String run,nonce,action;private File folder;private BroadcastReceiver receiver;
 public IBinder onBind(Intent i){return null;}
 private static byte[] read(File f,int max)throws IOException{FileInputStream in=new FileInputStream(f);try{return read(in,max);}finally{in.close();}}
 private static byte[] read(InputStream in,int max)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] c=new byte[2048];int n;while((n=in.read(c))!=-1){b.write(c,0,n);if(b.size()>max)throw new IOException("Input bound");}return b.toByteArray();}
 public int onStartCommand(Intent intent,int flags,int id){try{
  if(intent==null||!ARM.equals(intent.getAction())||controller!=null)throw new SecurityException("Explicit one arm only");
  LiveExecutionPolicy.requireReviewedActivation();
  if(!intent.getBooleanExtra("m6_separately_authorized",false))throw new SecurityException("Separate M6 authorization required in activated release");
  run=intent.getStringExtra("run_id");if(run==null||!run.matches("[A-Za-z0-9_-]{8,64}"))throw new SecurityException("Run id");folder=new File(getFilesDir(),"runs/"+run);if(!folder.mkdirs())throw new SecurityException("Fresh run only");
  File p=new File(getFilesDir(),"reviewed-m5");FileInputStream bundle=new FileInputStream(new File(p,"evidence.zip"));M5PassProof proof;InputStream cert=getAssets().open("project-reviewer.cer");try{proof=M5PassProof.verify(read(new File(p,"proof.m5review"),4096),read(new File(p,"proof.sig"),512),bundle,read(cert,8192));}finally{bundle.close();cert.close();}if(proof.synthetic)throw new SecurityException("No synthetic production proof");
  nonce=UUID.randomUUID().toString();action=getPackageName()+".PERMISSION."+nonce;UsbManager manager=(UsbManager)getSystemService(USB_SERVICE);usb=new AndroidAoaAdapter(this,manager,action);
  controller=new M6Controller(usb,new M6Journal(run,new M6Journal.Disk(new File(folder,"journal.txt"))),intent.getIntExtra("vendor_id",-1),intent.getIntExtra("product_id",-1),nonce);
  receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){UsbDevice d=(UsbDevice)i.getParcelableExtra(UsbManager.EXTRA_DEVICE);if(UsbManager.ACTION_USB_DEVICE_DETACHED.equals(i.getAction())||UsbManager.ACTION_USB_DEVICE_ATTACHED.equals(i.getAction())){usb.attachmentEvent(d);return;}if(!action.equals(i.getAction()))return;UsbIdentity target=controller.target();if(d==null||target==null||d.getVendorId()!=target.vendorId||d.getProductId()!=target.productId||d.getDeviceId()!=target.deviceId||!d.getDeviceName().equals(target.path))return;controller.permissionCallback(i.getStringExtra("nonce"),target,i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false));handler.removeCallbacks(tick);handler.post(tick);}};IntentFilter filter=new IntentFilter(action);filter.addAction(UsbManager.ACTION_USB_DEVICE_ATTACHED);filter.addAction(UsbManager.ACTION_USB_DEVICE_DETACHED);registerReceiver(receiver,filter);
  controller.begin(proof);if(controller.state()!=M6Controller.State.WAIT_TARGET)throw new SecurityException("Controller did not arm safely");FileOutputStream armed=new FileOutputStream(new File(folder,"armed.txt"));try{armed.write(("run="+run+"\nstate=WAIT_TARGET\nM5_proof="+proof.proofHash+"\n").getBytes("UTF-8"));armed.flush();armed.getFD().sync();}finally{armed.close();}handler.post(tick);
 }catch(Exception e){Log.i("RdxM6Aoa","REFUSED "+e.getClass().getSimpleName()+" "+e.getMessage());stopSelf();}return START_NOT_STICKY;}
 private final Runnable tick=new Runnable(){public void run(){try{controller.step();if(controller.terminal()){writeSummary();stopSelf();}else{M6Controller.State s=controller.state();boolean waiting=s==M6Controller.State.WAIT_TARGET||s==M6Controller.State.PERMISSION_PENDING||s==M6Controller.State.WAIT_DETACH||s==M6Controller.State.WAIT_REENUM;handler.postDelayed(this,waiting?500:0);}}catch(Exception e){controller.close();try{writeSummary();}catch(Exception ignored){}stopSelf();}}};
 private void writeSummary()throws IOException{String s="schema=1\nrun="+run+"\nstate="+controller.state()+"\nverdict="+controller.verdict()+"\nreason="+controller.reason()+"\ncausation="+controller.causation()+"\nstarts="+controller.starts()+"\ntransfers="+controller.transfers()+"\nlive_release_enabled="+LiveExecutionPolicy.EXECUTION_ENABLED+"\n";FileOutputStream o=new FileOutputStream(new File(folder,"summary.txt"));try{o.write(s.getBytes("UTF-8"));o.flush();o.getFD().sync();}finally{o.close();}}
 public void onDestroy(){handler.removeCallbacksAndMessages(null);if(controller!=null)controller.close();if(usb!=null)usb.close();if(receiver!=null){unregisterReceiver(receiver);receiver=null;}super.onDestroy();}
}
